<?php require '../includes/conexao.php'; require '../includes/verificar_login.php'; exigir_admin(); $alunos=$pdo->query("SELECT u.nome,u.email,p.xp,p.nivel,COUNT(r.id) partidas,COALESCE(SUM(r.acertos),0) acertos FROM usuarios u LEFT JOIN progresso p ON p.usuario_id=u.id LEFT JOIN resultados r ON r.usuario_id=u.id WHERE u.tipo='aluno' GROUP BY u.id,p.xp,p.nivel ORDER BY p.xp DESC")->fetchAll(); $titulo='Painel do professor'; $root='../'; $home='../dashboard.php'; include '../includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Visão do professor</div><h1 style="font-size:4rem">Painel de acompanhamento</h1><p>Consulte o avanço dos alunos na MathPlay.</p></div><a class="button secondary" href="resultados.php">Histórico completo</a></div><div class="card"><table><thead><tr><th>Aluno</th><th>E-mail</th><th>Nível</th><th>XP</th><th>Partidas</th><th>Acertos</th></tr></thead><tbody><?php foreach($alunos as $a): ?><tr><td><strong><?= htmlspecialchars($a['nome']) ?></strong></td><td><?= htmlspecialchars($a['email']) ?></td><td><?= $a['nivel'] ?></td><td><?= $a['xp'] ?></td><td><?= $a['partidas'] ?></td><td><?= $a['acertos'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php include '../includes/footer.php'; ?>
